// === ESTRUCTURA DEL PATRÓN ITERATOR ===

// 1. Interfaz Iterator (el contrato)
interface Iterator<T> {
  hasNext(): boolean;
  next(): T | null;
}

// 2. Interfaz Aggregate (la colección)
interface Aggregate<T> {
  createIterator(): Iterator<T>;
}

// 3. Colección Concreta
class Playlist implements Aggregate<Song> {
  private songs: Song[] = [];

  add(song: Song) { this.songs.push(song); }
  createIterator(): Iterator<Song> {
    return new PlaylistIterator(this.songs);
  }
}

// 4. Iterador Concreto
class PlaylistIterator implements Iterator<Song> {
  private position = 0;

  constructor(private songs: Song[]) {}

  hasNext(): boolean {
    return this.position < this.songs.length;
  }

  next(): Song | null {
    if (this.hasNext()) {
      return this.songs[this.position++];
    }
    return null;
  }
}

// Uso:
const playlist = new Playlist();
playlist.add(new Song('Bohemian Rhapsody'));
playlist.add(new Song('Stairway to Heaven'));

const iterator = playlist.createIterator();
while (iterator.hasNext()) {
  console.log(iterator.next()?.title);
}

