// 1. Interfaz Iterator común
interface Iterator<T> {
  hasNext(): boolean;
  next(): T | null;
}

// 2. Iterador concreto para la colección
class PlaylistIterator implements Iterator<Song> {
  private position = 0;
  constructor(private songs: Song[]) {}
  hasNext() { return this.position < this.songs.length; }
  next() { return this.songs[this.position++] ?? null; }
}

// 3. El cliente usa la interfaz sin conocer la estructura
function printSongs(iterator: Iterator<Song>) {
  while (iterator.hasNext()) {
    console.log(iterator.next()?.title);
  }
}

